Test("equality ignores case and surrounding spaces", () =>
{
    Ok(new Email(" Ana@Example.com ") == new Email("ana@example.com"), "== should be true");
    Ok(new Email("Ana@Example.com").Equals(new Email("ANA@EXAMPLE.COM")), "Equals should be true");
    Ok(new Email("a@x.io") != new Email("b@x.io"), "!= should be true for different addresses");
});

Test("works as a HashSet and Dictionary key", () =>
{
    var set = new HashSet<Email> { new Email("Ana@Example.com"), new Email(" ana@example.com") };
    Eq(set.Count, 1);
    var d = new Dictionary<Email, int> { [new Email("BO@x.io")] = 7 };
    Eq(d[new Email("bo@X.io")], 7);
});

Test("Equals(object) and null handling", () =>
{
    object other = new Email("a@x.io");
    Ok(new Email("A@x.io").Equals(other), "Equals(object)");
    Ok(!new Email("a@x.io").Equals(null), "Equals(null) must be false");
    Ok(!(new Email("a@x.io") == null), "email == null must be false");
    Email? none = null;
    Ok(none == null, "null == null must be true");
});

Test("Value and ToString are normalised", () =>
{
    var e = new Email("  Ana@Example.COM ");
    Eq(e.Value, "ana@example.com");
    Eq(e.ToString(), "ana@example.com");
});

Test("a blank address throws (boundary)", () =>
    Throws<ArgumentException>(() => new Email("   ")));

