sealed class Email : IEquatable<Email>
{
    public Email(string raw)
    {
        if (string.IsNullOrWhiteSpace(raw)) throw new ArgumentException("an email address is required", nameof(raw));
        Value = raw.Trim().ToLowerInvariant();
        _raw = raw;
    }

    private readonly string _raw;

    public string Value { get; } = "";

    public bool Equals(Email? other) => other is not null && Value == other.Value;

    public override bool Equals(object? obj) => Equals(obj as Email);

    public override int GetHashCode() => _raw.GetHashCode();

    public override string ToString() => Value;

    public static bool operator ==(Email? a, Email? b) => a is null ? b is null : a.Equals(b);

    public static bool operator !=(Email? a, Email? b) => !(a == b);
}

